  if (body && Array.isArray(body.opportunities)) return body.opportunities;
  if (body && Array.isArray(body.data)) return body.data;
  if (body && Array.isArray(body.items)) return body.items;
  return [];
}

async function requestJson(url, qs) {
  try {
    return await this.helpers.httpRequest({
      method: 'GET',
      url,
      qs,
      headers,
      json: true,
      timeout: 60000,
    });
  } catch (error) {
    const details = (error && error.response && error.response.body)
      || (error && error.cause && error.cause.response && error.cause.response.body)
      || error.message
      || error;
    throw new Error('GHL opportunities search failed for ' + url + ': ' + (typeof details === 'string' ? details : JSON.stringify(details)));
